import{_ as o,r,o as n,c as s,a as t,b as i,d as l,e as h}from"./chunks/framework.8NMv9ABN.js";const y=JSON.parse('{"title":"Analyzer","description":"","frontmatter":{},"headers":[],"relativePath":"en/tools/analyzer.md","filePath":"en/tools/analyzer.md"}'),d={name:"en/tools/analyzer.md"};function c(p,e,u,g,m,b){const a=r("Screenshot");return n(),s("div",null,[e[0]||(e[0]=t("h1",{id:"analyzer",tabindex:"-1"},[i("Analyzer "),t("a",{class:"header-anchor",href:"#analyzer","aria-label":'Permalink to "Analyzer"'},"​")],-1)),e[1]||(e[1]=t("p",null,"Analyzer is the chart workspace: one ticker, several timeframes side by side, on whichever exchange you choose. It is the only tool where you draw on charts.",-1)),l(a,{src:"analyzer",alt:"The Analyzer window with four charts, ticker list and watchlist",caption:"The Analyzer window"}),e[2]||(e[2]=h('<p>Unlike the other tools, Analyzer has almost nothing to configure in the main window — everything is controlled from the window itself, and your layout is remembered between sessions.</p><h2 id="layout" tabindex="-1">Layout <a class="header-anchor" href="#layout" aria-label="Permalink to &quot;Layout&quot;">​</a></h2><p>The window has two parts: a list panel on the left holding <strong>Markets</strong> and <strong>Watchlist</strong>, and the chart area on the right.</p><h2 id="choosing-what-to-chart" tabindex="-1">Choosing what to chart <a class="header-anchor" href="#choosing-what-to-chart" aria-label="Permalink to &quot;Choosing what to chart&quot;">​</a></h2><h3 id="exchange" tabindex="-1">Exchange <a class="header-anchor" href="#exchange" aria-label="Permalink to &quot;Exchange&quot;">​</a></h3><p>Five exchange buttons: <strong>Bybit</strong>, <strong>Binance</strong>, <strong>Gate</strong> (Gate.io), <strong>OKX</strong> and <strong>Hyper</strong> (Hyperliquid). Switching exchange reloads the ticker list and repoints every chart at the new exchange without a reload.</p><p>Drawings are stored per symbol <em>and</em> per exchange, so the same ticker on two exchanges keeps two separate sets of drawings.</p><h3 id="market-type" tabindex="-1">Market type <a class="header-anchor" href="#market-type" aria-label="Permalink to &quot;Market type&quot;">​</a></h3><p><strong>FUT</strong> (perpetual futures) or <strong>SPOT</strong>. This changes which markets are listed and which metrics exist — see <a href="#metric-columns">Metric columns</a>.</p><p>Switching to SPOT resets the active metric to 24H%, since spot markets have no open interest or funding rate.</p><h3 id="search" tabindex="-1">Search <a class="header-anchor" href="#search" aria-label="Permalink to &quot;Search&quot;">​</a></h3><p>The search box filters the ticker list, and it is deliberately forgiving:</p><ul><li>Punctuation, spaces, dashes and slashes are ignored.</li><li>Queries of three characters or more tolerate a dropped or mistyped character.</li><li><strong>Cyrillic input is transliterated by keyboard position.</strong> Typing <code>ИЕСГІВЕ</code> with a Ukrainian layout active matches <code>BTCUSDT</code>, because those are the same physical keys. You don&#39;t have to switch layout to search.</li></ul><h3 id="metric-columns" tabindex="-1">Metric columns <a class="header-anchor" href="#metric-columns" aria-label="Permalink to &quot;Metric columns&quot;">​</a></h3><p>The list shows a symbol column plus one or more metric columns:</p><table tabindex="0"><thead><tr><th>Column</th><th>Meaning</th><th>Markets</th></tr></thead><tbody><tr><td><strong>24H%</strong></td><td>Price change over 24h</td><td>Futures and spot</td></tr><tr><td><strong>VOL</strong></td><td>Trading volume over 24h, in USD</td><td>Futures and spot</td></tr><tr><td><strong>OI</strong></td><td>Open interest — total open positions, in USD</td><td>Futures only</td></tr><tr><td><strong>FR</strong></td><td>Funding rate</td><td>Futures only</td></tr></tbody></table><p>Click a column header to sort by it; click again to reverse the direction. An arrow marks the active sort.</p><p>How many columns are visible <strong>depends on how wide the panel is</strong>. Narrow the panel and it falls back to showing only the active metric; widen it and the columns reappear one at a time. Markets and Watchlist are measured separately, so they can be showing different numbers of columns at the same time.</p><h3 id="watchlist" tabindex="-1">Watchlist <a class="header-anchor" href="#watchlist" aria-label="Permalink to &quot;Watchlist&quot;">​</a></h3><p>Add a ticker from the Markets list with its <strong>+</strong> button; remove it from the Watchlist with <strong>×</strong>. Each watchlist entry shows the logos of the exchanges that list it — hovering one reads <code>Listed on &lt;exchange&gt;</code>.</p><p>Listing badges reflect the <strong>current market type</strong>: a token that only trades on spot won&#39;t badge while you are in futures.</p><p>The watchlist persists between sessions.</p><h2 id="charts" tabindex="-1">Charts <a class="header-anchor" href="#charts" aria-label="Permalink to &quot;Charts&quot;">​</a></h2><h3 id="panels" tabindex="-1">Panels <a class="header-anchor" href="#panels" aria-label="Permalink to &quot;Panels&quot;">​</a></h3><p>Analyzer opens with four chart panels at <strong>5m, 15m, 1h and 4h</strong>. That is a starting point, not a fixed layout:</p><ul><li><strong>Add chart</strong> adds a panel, up to <strong>8</strong>.</li><li><strong>Close chart</strong> removes one, down to a minimum of <strong>1</strong>.</li><li>Each panel has its own timeframe dropdown: <code>1m</code>, <code>5m</code>, <code>15m</code>, <code>30m</code>, <code>1h</code>, <code>4h</code>, <code>1d</code>, <code>1w</code>.</li></ul><p>Your panel layout and each panel&#39;s timeframe are saved, so the window comes back the way you left it.</p><h3 id="history" tabindex="-1">History <a class="header-anchor" href="#history" aria-label="Permalink to &quot;History&quot;">​</a></h3><p>Scroll left on any chart to load older candles automatically, in batches, as far back as the exchange provides.</p><h3 id="fullscreen" tabindex="-1">Fullscreen <a class="header-anchor" href="#fullscreen" aria-label="Permalink to &quot;Fullscreen&quot;">​</a></h3><p>Each panel has an expand button that opens it fullscreen. In fullscreen the timeframe dropdown gains a star next to each entry — starred timeframes appear as a quick-access row, shared with the fullscreen views in Knives and Monitor.</p><p>Press <kbd>Esc</kbd> or the close button to exit.</p><h3 id="drawing-tools" tabindex="-1">Drawing tools <a class="header-anchor" href="#drawing-tools" aria-label="Permalink to &quot;Drawing tools&quot;">​</a></h3><p>Five tools are available on every chart, each on its own key:</p><table tabindex="0"><thead><tr><th>Tool</th><th>Default key</th></tr></thead><tbody><tr><td>Horizontal ray</td><td><kbd>H</kbd></td></tr><tr><td>Trend line</td><td><kbd>T</kbd></td></tr><tr><td>Rectangle</td><td><kbd>B</kbd></td></tr><tr><td>Pencil</td><td><kbd>P</kbd></td></tr><tr><td>Dissolving pencil</td><td><kbd>F</kbd></td></tr></tbody></table><p>Hold <kbd>Ctrl</kbd> while placing a point to snap it to the nearest candle high or low.</p><p>The active tool is tracked <strong>per chart panel</strong>, so you can be drawing a trend line on one panel while another is idle.</p><p>Keys, drawing color and magnet behaviour are all configurable — see <a href="/manual/en/customize/chart-colors.html">Charts &amp; drawing</a>.</p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><p>The <strong>Analyzer</strong> tab in the main window carries no settings. It holds the <strong>Open Window</strong> button and a notices section.</p><h3 id="known-issues" tabindex="-1">Known issues <a class="header-anchor" href="#known-issues" aria-label="Permalink to &quot;Known issues&quot;">​</a></h3><p>The tab reports one known limitation, quoted from the app:</p><blockquote><p>Gate.io charts take longer to load compared to other exchanges. This is a known limitation and a fix is being worked on.</p></blockquote><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/manual/en/customize/chart-colors.html">Charts &amp; drawing</a> — candle colors, drawing color, tool shortcuts, magnet</li><li><a href="/manual/en/tools/monitor.html">Monitor</a> — ranked scanner; its cards also open fullscreen charts with the same drawing tools</li></ul>',45))])}const k=o(d,[["render",c]]);export{y as __pageData,k as default};
